export function memoryAuditSample(workspaceId: string): readonly { readonly scope: MemoryScope; readonly entry: MemoryEntry }[] {
  return [...globalSubjects, ...workspaceSubjects].map((title, index) => ({
    scope: index < globalSubjects.length ? { kind: 'global' } : { kind: 'workspace', workspaceId },
    entry: {
      id: `m_sample_${String(index + 1).padStart(2, '0')}`, title,
      type: index === 62 ? 'reference' : index >= 47 ? 'project' : 'feedback',
      body: bodies[index]!,
      status: 'active', pinned: false, created: '2026-10-01T00:00:00.000Z', updated: '2026-10-05T00:00:00.000Z',
      source: { writer: 'agent', session: 'sample_session' }, reason: 'Anonymized subject representative', revision: `sample-revision-${index + 1}`,
    },
  }));
}
